// src/index.ts
import { parse } from "sql-parser-cst";

// src/utils.ts
var isDefined = (value) => value !== void 0;
var isString = (value) => typeof value === "string";
var isObject = (x) => typeof x === "object" && x !== null && !(x instanceof Array);
var isArray = (x) => Array.isArray(x);
var isEmptyArray = (x) => isArray(x) && x.length === 0;
var isNode = (value) => isObject(value) && isString(value.type) && !isCommentType(value.type);
var isCommentType = (type) => type === "block_comment" || type === "line_comment";
var arrayWrap = (x) => isArray(x) ? x : [x];
var last = (arr) => arr[arr.length - 1];

// src/syntax/alias.ts
var aliasMap = {
  alias: (print) => print.spaced(["expr", "asKw", "alias", "columnAliases"])
};

// src/print_utils.ts
import { doc, util } from "prettier";
var {
  line,
  hardline,
  softline,
  indent,
  group,
  lineSuffix,
  ifBreak,
  breakParent
} = doc.builders;
var { join: origJoin } = doc.builders;
var { stripTrailingHardline } = doc.utils;
var join = (sep, docs) => isArray(docs) ? origJoin(sep, docs) : docs;
var containsNewline = (node, opts) => {
  if (!node.range) {
    throw new Error("containsNewline() expected a Node with range info");
  }
  return util.hasNewlineInRange(
    opts.originalText,
    node.range[0],
    node.range[1]
  );
};
var hasEmptyLineBetweenNodes = (node1, node2, opts) => {
  if (!node1.range || !node2.range) {
    throw new Error("emptyLineBetweenNodes() expects Nodes with range info");
  }
  const start = node1.range[1];
  const end = node2.range[0];
  const indexes = emptyLineIndexes(opts.originalText.slice(start, end)).map(
    (i) => start + i
  );
  if (indexes.length === 0) {
    return false;
  }
  const comments = [...node1.trailing ?? [], ...node2.leading ?? []];
  return indexes.filter((index) => !isIndexInsideOrBetweenComments(index, comments)).length > 0;
};
function emptyLineIndexes(text) {
  const indexes = [];
  const re = /\n[ \t]*\r?\n/g;
  let match;
  while (match = re.exec(text)) {
    indexes.push(match.index);
  }
  return indexes;
}
function isIndexInsideOrBetweenComments(index, comments) {
  if (comments.length === 0) {
    return false;
  }
  const start = comments[0].range[0];
  const end = comments[comments.length - 1].range[1];
  return start <= index && index <= end;
}

// src/syntax/constraint.ts
var constraintMap = {
  /** cst-ignore: constraint, modifiers */
  constraint: (print, node) => {
    if (node.name) {
      return group([
        print("name"),
        indent([line, printUnnamedConstraint(print, node)])
      ]);
    } else {
      return printUnnamedConstraint(print, node);
    }
  },
  constraint_name: (print) => print.spaced(["constraintKw", "name"]),
  constraint_modifier: (print) => print.spaced("kw"),
  constraint_null: (print) => print("nullKw"),
  constraint_not_null: (print) => group(print.spaced(["notNullKw", "clauses"])),
  constraint_default: (print) => group(print.spaced(["defaultKw", "expr"])),
  constraint_primary_key: (print) => group(print.spaced(["primaryKeyKw", "direction", "columns", "clauses"])),
  constraint_unique: (print) => group(print.spaced(["uniqueKw", "columns", "nullsKw", "clauses"])),
  existing_index: (print) => print.spaced(["usingIndexKw", "index"]),
  constraint_check: (print) => group(print.spaced(["checkKw", "expr", "clauses"])),
  constraint_collate: (print) => group(print.spaced(["collateKw", "collation"])),
  constraint_foreign_key: (print) => group(print.spaced(["foreignKeyKw", "indexName", "columns", "references"])),
  references_specification: (print, node) => {
    const baseDoc = print.spaced(["referencesKw", "table", "columns"]);
    if (node.options.length > 0) {
      return group([
        baseDoc,
        indent([hardline, join(hardline, print("options"))])
      ]);
    } else {
      return baseDoc;
    }
  },
  referential_action: (print) => print.spaced(["onKw", "eventKw", "actionKw", "columns"]),
  referential_match: (print) => print.spaced(["matchKw", "typeKw"]),
  constraint_generated: (print) => print.spaced([
    "generatedKw",
    "asKw",
    "expr",
    "storageKw",
    "sequenceOptions"
  ]),
  identity_column: (print) => print("identityKw"),
  constraint_auto_increment: (print) => print("autoIncrementKw"),
  on_conflict_clause: (print) => print.spaced(["onConflictKw", "resolutionKw"]),
  constraint_comment: (print) => print.spaced(["commentKw", "value"]),
  constraint_index: (print) => print.spaced(["indexTypeKw", "indexKw", "columns"]),
  constraint_visible: (print) => print.spaced(["visibleKw"]),
  constraint_column_format: (print) => print.spaced(["columnFormatKw", "formatKw"]),
  constraint_storage: (print) => print.spaced(["storageKw", "typeKw"]),
  constraint_engine_attribute: (print, node) => join(node.hasEq ? " = " : " ", print(["engineAttributeKw", "value"])),
  constraint_compression: (print) => print.spaced(["compressionKw", "method"]),
  constraint_exclude: (print, node) => group([
    print("excludeKw"),
    indent([
      line,
      join(line, [
        print.separated(line, ["using", "params"]),
        ...print("clauses")
      ])
    ])
  ]),
  exclusion_param: (print) => print.spaced(["index", "withKw", "operator"]),
  index_tablespace_clause: (print) => print.spaced(["usingIndexTablespaceKw", "name"])
};
var printUnnamedConstraint = (print, node) => {
  if (node.modifiers.length > 0) {
    return group([
      print("constraint"),
      indent([line, print.spaced("modifiers")])
    ]);
  } else {
    return print("constraint");
  }
};

