// src/node_utils.ts
var is = (type) => (node) => isObject(node) && node.type === type;
var isProgram = is("program");
var isValuesClause = is("values_clause");
var isFuncCall = is("func_call");
var isFuncArgs = is("func_args");
var isCreateTableStmt = is("create_table_stmt");
var isKeyword = is("keyword");
var isEmpty = is("empty");
var isJsonLiteral = is("json_literal");
var isJsonbLiteral = is("jsonb_literal");
var isStringLiteral = is("string_literal");
var isArraySubscript = is("array_subscript");
var isAsClause = is("as_clause");
var isParenExpr = is("paren_expr");
var isMemberExpr = is("member_expr");
var isSelectStmt = is("select_stmt");
var isCompoundSelectStmt = is("compound_select_stmt");
var isListExpr = is("list_expr");
var isCreateFunctionStmt = is("create_function_stmt");
var isAlterFunctionStmt = is("alter_function_stmt");
var isDropFunctionStmt = is("drop_function_stmt");
var isCreateProcedureStmt = is("create_procedure_stmt");
var isAlterProcedureStmt = is("alter_procedure_stmt");
var isDropProcedureStmt = is("drop_procedure_stmt");
var isAlterActionRename = is("alter_action_rename");
var isLanguageClause = is("language_clause");
var isDynamicallyLoadedFunction = is("dynamically_loaded_function");
var isBigqueryQuotedMemberExpr = is("bigquery_quoted_member_expr");
var isCreateTriggerStmt = is("create_trigger_stmt");
var isExecuteClause = is("execute_clause");
var isFunctionSignature = is("function_signature");
var isDataTypeName = is("data_type_name");
var isIntervalDataType = is("interval_data_type");
var isIntervalUnit = is("interval_unit");
var isIntervalUnitRange = is("interval_unit_range");
var isTimeDataType = is("time_data_type");
var isParametricDataType = is("parametric_data_type");
var isDataType = ([node, ...ancestors]) => isDataTypeName(node) || isIntervalDataType(node) || isIntervalUnit(node) && isDataType(ancestors) || isIntervalUnitRange(node) && isDataType(ancestors) || isTimeDataType(node) || isParametricDataType(node);

// src/syntax/base.ts
var baseMap = {
  /** cst-ignore: name */
  keyword: (print, node, path, options2) => {
    const keywordCase = isDataType(path.ancestors) ? options2.sqlTypeCase : options2.sqlKeywordCase;
    switch (keywordCase) {
      case "preserve":
        return path.node.text;
      case "upper":
        return path.node.text.toUpperCase();
      case "lower":
        return path.node.text.toLowerCase();
    }
  },
  all_columns: () => "*",
  empty: () => []
};

