  with_partition_columns_clause: (print) => print.spaced(["withPartitionColumnsKw", "columns"]),
  create_table_using_clause: (print) => print.spaced(["usingKw", "module"]),
  create_table_inherits_clause: (print) => print.spaced(["inheritsKw", "tables"]),
  create_table_partition_by_clause: (print) => print.spaced(["partitionByKw", "strategyKw", "columns"]),
  create_table_partition_of_clause: (print) => print.spaced(["partitionOfKw", "table"]),
  create_table_partition_bound_clause: (print) => print.spaced(["forValuesKw", "bound"]),
  partition_bound_in: (print) => print.spaced(["inKw", "values"]),
  partition_bound_from_to: (print) => print.spaced(["fromKw", "from", "toKw", "to"]),
  partition_bound_minvalue: (print) => print.spaced("minvalueKw"),
