var printLiteral = (node, options2) => {
  switch (options2.sqlLiteralCase) {
    case "preserve":
      return node.text;
    case "upper":
      return node.text.toUpperCase();
    case "lower":
      return node.text.toLowerCase();
  }
};
var printIdentifier = (node, options2) => {
  switch (options2.sqlIdentifierCase) {
    case "preserve":
      return node.text;
    case "upper":
      return node.text.toUpperCase();
    case "lower":
      return node.text.toLowerCase();
  }
};
var printFunctionName = (node, options2) => {
  switch (options2.sqlFunctionCase) {
    case "preserve":
      return node.text;
    case "upper":
      return node.text.toUpperCase();
    case "lower":
      return node.text.toLowerCase();
  }
};
var isQuotedIdentifier = (node) => node.name !== node.text;
var isQuotedVariable = (node) => !(node.text === "@" + node.name || node.text === "@@" + node.name);
var isQuotedParameter = (node) => /`$/.test(node.text);
