// src/syntax/program.ts
var programMap = {
  program: (print, node, path, options2) => print("statements").map(
    (doc2, i) => i === node.statements.length - 1 ? printFinalStatement(doc2, i, node.statements, options2) : printStatement(doc2, i, node.statements, options2)
  )
};
var printStatement = (doc2, i, statements, options2) => {
  const prevNode = statements[i - 1];
  const node = statements[i];
  if (i === 0) {
    return doc2;
  } else if (node.type !== "empty") {
    if (hasEmptyLineBetweenNodes(prevNode, node, options2)) {
      return [";", hardline, hardline, doc2];
    } else {
      return [";", hardline, doc2];
    }
  } else {
    return [";", hardline, doc2];
  }
};
var printFinalStatement = (doc2, i, statements, options2) => {
  const stmtDoc = printStatement(doc2, i, statements, options2);
  if (statements[i].type === "empty") {
    return stmtDoc;
  } else {
    return [stmtDoc, hardline];
  }
};

